exec(open('test_carnet.py').read().split("with sync_playwright() as p:")[0])
import datetime
td = datetime.date.today().isoformat()
prices = [{'name': n, 'price': p} for n, p in [("Plaquettes de frein avant", 189), ("Plaquettes de frein arrière", 179), ("Disques de frein avant", 249), ("Liquide de frein (purge)", 89), ("Étrier de frein", 229), ("Câble de frein à main", 129), ("Inspection des freins", 49), ("Changement d'huile synthétique", 109.99), ("Remplacement de l'alternateur", 399)]]
seed = {'config/main': {'biz': {'name': 'Garage Test'}, 'mechanics': ['Ali'], 'services': prices},
        'clients/c1': {'firstName': 'Jean', 'lastName': 'Test', 'phone': '(514) 555-0000', 'address': '1 rue Test, Montréal H4P 2B5', 'postal': 'H4P 2B5', 'notes': []},
        'jobs/j1': {'client': {'name': 'Jean Test', 'postal': 'H4P 2B5'}, 'clientId': 'c1', 'vehicle': {}, 'services': ['Flushing des freins (client)'], 'date': td, 'time': '09:00', 'durationMin': 60, 'mechanic': 'Ali', 'status': 'termine'}}
def rows(pg): return [r.inner_text().split('\n')[0] for r in pg.locator('#svc-opts .opt:not(.new)').all()]
def typ(pg, t): pg.fill('#f-svc-in', ''); pg.click('#f-svc-in'); pg.keyboard.type(t); pg.wait_for_timeout(80)
with sync_playwright() as p:
    br = p.chromium.launch()
    ctx, pg, errs = new_page(br, {'seed': seed})
    pg.click('#top [data-act="new"]'); pg.wait_for_timeout(250); sheet_pick_client(pg, 'jean')
    typ(pg, 'frein')
    r = rows(pg)
    want = [n for n in ["Plaquettes de frein avant", "Plaquettes de frein arrière", "Disques de frein avant", "Liquide de frein (purge)", "Étrier de frein", "Câble de frein à main", "Inspection des freins", "Flushing des freins (client)", 'Freins avant (plaquettes et disques)', 'Freins arrière (plaquettes et disques)']]
    check('V1. "frein": every service containing the word, even in the middle (10, more than the old limit of 8)', sorted(r) == sorted(want) and len(r) == 10, r)
    check('V1b. Ones starting with the word come first', r[:2] == ['Freins avant (plaquettes et disques)', 'Freins arrière (plaquettes et disques)'], r[:3])
    check('V2. Count line "10 services avec « frein »" and the word highlighted in each', '10 services avec « frein »' in pg.inner_text('#svc-opts .opt-count') and pg.locator('#svc-opts .opt:not(.new) mark').count() >= 10 and all(m.lower().startswith('frein') for m in pg.locator('#svc-opts .opt:not(.new) mark').all_inner_texts()), pg.locator('#svc-opts mark').all_inner_texts()[:5])
    pg.wait_for_timeout(500)
    inview = pg.evaluate("(function(){ var b = document.querySelectorAll('#svc-opts .opt'); if (!b.length) return 0; var n = 0; b.forEach(function(x){ var r = x.getBoundingClientRect(); if (r.top >= 0 && r.bottom <= innerHeight) n++; }); return n; })()")
    check('V2b. On a phone screen the list comes into view as soon as you type (at least 4 rows visible)', inview >= 4, inview)
    pg.screenshot(path=os.path.join(SC, 'shot_svc_search.png'))
    typ(pg, 'nateur')
    check('V3. Part of a word ("nateur") finds "alternateur"', rows(pg) == ["Remplacement de l'alternateur"] and pg.locator('#svc-opts mark').first.inner_text() == 'nateur', rows(pg))
    typ(pg, 'demarreur')
    check('V4. Without accents ("demarreur") finds "démarreur", highlight on the real letters', rows(pg) == ['Remplacement du démarreur'] and pg.locator('#svc-opts mark').first.inner_text() == 'démarreur', rows(pg))
    typ(pg, 'huile')
    check('V5. "huile" finds both oil changes (inside "d\'huile") first, then the promo that includes it', sorted(rows(pg)[:2]) == sorted(["Changement d'huile synthétique", "Changement d'huile et filtre"]) and len(rows(pg)) == 3 and 'PROMO' in rows(pg)[2].upper(), rows(pg))
    typ(pg, 'avant plaquettes')
    check('V6. Two words in any order', sorted(rows(pg)) == sorted(['Plaquettes de frein avant', 'Freins avant (plaquettes et disques)']), rows(pg))
    typ(pg, 'courroie')
    check('V7. Unknown phrase still offered "+ Ajouter"', pg.locator('#svc-opts .opt.new').count() == 1 and len(rows(pg)) == 2)
    typ(pg, 'frein')
    for _ in range(9): pg.keyboard.press('ArrowDown')
    act = pg.evaluate("document.getElementById('f-svc-in').getAttribute('aria-activedescendant')")
    vis = pg.evaluate("(function(){ var b = document.getElementById('svc-opts'), a = document.querySelector('#svc-opts .opt.active'); if (!a) return false; var br = b.getBoundingClientRect(), ar = a.getBoundingClientRect(); return ar.top >= br.top - 1 && ar.bottom <= br.bottom + 1; })()")
    check('V8. Arrow keys reach the 10th match and the list scrolls to keep it in view', act == 'svc-opt-9' and vis, (act, vis))
    pg.keyboard.press('Enter'); pg.wait_for_timeout(100)
    check('V8b. Enter adds it', len(pg.locator('#svc-picked .pchip').all()) == 1 and pg.input_value('#f-svc-in') == '')
    typ(pg, 'frein')
    check('V9. Already-picked service no longer offered (9 left)', len(rows(pg)) == 9 and '9 services avec « frein »' in pg.inner_text('#svc-opts .opt-count'))
    pg.locator('#svc-opts .opt', has_text='Étrier').click(); pg.wait_for_timeout(100)
    check('V10. Tap adds it too', len(pg.locator('#svc-picked .pchip').all()) == 2)
    pg.fill('#f-svc-in', ''); pg.click('#f-time'); pg.click('#f-svc-in'); pg.wait_for_timeout(80)
    check('V11. Empty field: a short list and a tip to type a word', len(rows(pg)) <= 8 and 'Tape un mot' in pg.inner_text('#svc-opts .opt-count'))
    check('V12. No script errors, no side-scroll', not errs and no_hscroll(pg), errs[:3])
    ctx.close()
    ctx, pg, errs = new_page(br, {'seed': seed}, scheme='dark')
    pg.click('#top [data-act="new"]'); pg.wait_for_timeout(250); sheet_pick_client(pg, 'jean'); typ(pg, 'frein'); pg.wait_for_timeout(500)
    pg.screenshot(path=os.path.join(SC, 'shot_svc_dark.png'))
    check('V13. Dark mode renders, no errors', len(rows(pg)) == 10 and not errs, errs[:3])
    ctx.close(); br.close()
print('\n%d/%d passed' % (sum(1 for r in results if r[1]), len(results)))
